insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('3db7dc7b-bc2a-4946-985f-b7e3126854bf', 'c558e2e6-a4d4-48f4-8cbf-9a302f6f92f3', $$vacature voor een tijdelijke docent per 1 november 2024$$,
   $$bedrijfseconomie-havo-2026-i-vacature-docent-nederlands-context1.png$$,
   $$Een middelbare school zoekt een nieuwe docent om per
1 november 2024 een vacature in te vullen. Het gaat om een tijdelijke functie tot het einde van het schooljaar op 31 juli 2025. De beloning is gebaseerd op salarisschaal LB volgens de cao voor het voortgezet onderwijs.
De school gebruikt bij de werving van de docent het onderstaande functieprofiel.$$, 'inline'),
  ('39c77e25-1c94-432e-8ede-031b8932228d', 'c558e2e6-a4d4-48f4-8cbf-9a302f6f92f3', $$functieprofiel docent Nederlands$$,
   $$bedrijfseconomie-havo-2026-i-vacature-docent-nederlands-context2.png$$,
   $$Functieprofiel
functie | docent Nederlands
taken en verantwoordelijkheden | het geven van inspirerende lessen aan leerlingen van havo 1 tot en met havo 3; het ontwikkelen van lesmateriaal en het mentoraat van een brugklas
vaardigheden | ICT-vaardigheden en sociale vaardigheden.
arbeidsvoorwaarden | conform cao voortgezet onderwijs, salarisschaal LB. Behalve het brutoloon en vakantiegeld biedt de school ook andere beloningsvormen zoals ...(a)….
contractomvang | 0,7 fte¹⁾
type arbeidsovereenkomst | contract voor ...(b)…
vereiste kwalificaties | tweedegraads onderwijsbevoegdheid Nederlands
noot 1 1 fte: een volledige baan$$, 'inline'),
  ('be1df1a6-bcf7-4964-899f-44a577665220', 'c558e2e6-a4d4-48f4-8cbf-9a302f6f92f3', $$vacaturetekst op de eigen website en op vacaturebanken$$,
   $$bedrijfseconomie-havo-2026-i-vacature-docent-nederlands-context3.png$$,
