  ('d9d514a0-caa8-4133-9977-24fe1e8ca38d', '307eb6b3-925b-48d3-ad48-f95f9738839a', $$Coolblue bv overweegt een beursgang met aandelenemissie$$,
   $$bedrijfseconomie-havo-2026-i-coolblue-bv-context1.png$$,
   $$Coolblue bv is een (web)winkel die huishoudelijke apparatuur zoals wasmachines verkoopt. De aandelen van Coolblue zijn in handen van de oorspronkelijke oprichter Pieter Zwart (51%) en investeringsmaatschappij HAL (49%). In het najaar van 2021 overwoog Coolblue een beursgang met een emissie van nieuwe aandelen Coolblue.
De aandelenemissie was nodig ter verbetering van de solvabiliteit (EV/VV) en voor de financiering van nieuwe investeringen.$$, 'inline'),
  ('6ad90a14-0731-43cb-ba2c-2e9594659575', '307eb6b3-925b-48d3-ad48-f95f9738839a', $$beursgang uitgesteld door de komst van Amazon$$,
   $$bedrijfseconomie-havo-2026-i-coolblue-bv-context2.png$$,
   $$De beursgang en aandelenemissie van Coolblue werd uitgesteld door de komst van concurrent Amazon in Nederland. Hierdoor hadden potentiële beleggers geen interesse meer in de aandelenemissie van Coolblue.$$, 'inline'),
  ('9fef5e3a-7f4c-4086-b447-eb37aa918a1a', '307eb6b3-925b-48d3-ad48-f95f9738839a', $$leveranciers financierden de uitbreiding van Coolblue$$,
   $$bedrijfseconomie-havo-2026-i-coolblue-bv-context3.png$$,
   $$Tot 2021 hebben leveranciers de uitbreiding van Coolblue gefinancierd. Coolblue koopt wasmachines voor de (web)winkels in bij diverse leveranciers. Deze leveranciers worden pas een maand na levering van de goederen betaald.$$, 'inline'),
  ('43c27f68-a59d-4c7e-b6d4-6b5a1d185516', '9eba80c2-6014-40bd-9b97-31509914dc2e', $$inleiding: dividendbelasting buiten beschouwing; N@Home nv$$,
