  ('f9b37e42-f2ab-42f3-8058-30b93eed0c98', 'e67b7c4e-9bbc-48a5-89f9-c8b18ada769a', $$Ada en Chris willen trouwen en een huis kopen met eigen geld$$,
   $$bedrijfseconomie-havo-2026-i-ada-en-chris-context1.png$$,
   $$Ada en Chris hebben plannen om te trouwen en daarna een huis te kopen. Voor de aankoop van een huis willen ze eigen geld inbrengen: Chris € 50.000 en Ada € 25.000. Omdat Chris meer spaargeld inbrengt wil hij in geval van een scheiding een groter aandeel van de waardestijging van het huis. Ada is hiermee akkoord.
Ada en Chris gaan trouwen in de vorm waarbij dit mogelijk is.$$, 'inline'),
  ('6c017a41-5beb-4883-b197-b1d5b548d979', 'e67b7c4e-9bbc-48a5-89f9-c8b18ada769a', $$aankoop woning van € 450.000 met hypothecaire lening$$,
   $$bedrijfseconomie-havo-2026-i-ada-en-chris-context2.png$$,
   $$Ada en Chris kopen op 1 januari 2025 een woning voor een koopsom van € 450.000. Voor de financiering gebruiken ze, naast het ingebrachte spaargeld, voor het overige deel een hypothecaire lening bij de bank.$$, 'inline'),
